import {ATTRIBUTES,ITEM_BY_ID,ITEMS,SLOTS,ACTIONS,CHAMPIONS} from './gladiator-data.js';
export const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export const clone=o=>JSON.parse(JSON.stringify(o));
export function makeGladiator({id='g-'+Date.now().toString(36),name='New Gladiator',appearance={},attributes={},difficulty=1}={}){return {id,name:String(name).trim().slice(0,24)||'New Gladiator',appearance:{skin:'#d79a66',hair:'#573b29',hairStyle:'short',beard:'none',eyes:'brave',body:1,...appearance},attributes:Object.fromEntries(Object.keys(ATTRIBUTES).map(k=>[k,clamp(Math.round(attributes[k]||3),3,13)])),difficulty:clamp(difficulty,0,2),level:1,xp:0,gold:140,skillPoints:0,equipped:{weapon:'w-club-1'},inventory:['w-club-1'],wins:0,losses:0,champions:[],battles:0};}
export function equipment(g){return Object.fromEntries(Object.entries(g.equipped||{}).map(([k,v])=>[k,ITEM_BY_ID[v]]).filter(([,v])=>v));}
export function fighterStats(g){const a=g.attributes,e=equipment(g);return {maxHp:40+a.vitality*7+g.level*5,maxEnergy:36+a.stamina*7+g.level*2,armor:Object.values(e).reduce((s,i)=>s+(i.armor||0),0),damage:(e.weapon?.damage||5)+a.strength*1.6,reach:e.weapon?.reach||65,accuracy:e.weapon?.accuracy||0,block:Math.min(42,(e.shield?.block||0)+a.defence*.7),dodge:Math.min(24,a.agility*.65+a.defence*.35),walk:60+a.agility*3,jump:100+a.agility*5,recovery:14+a.stamina*2};}
export function priceFor(g,item){return Math.max(1,Math.round(item.price*(1-Math.min(.25,g.attributes.charisma*.012))));}
export function buyItem(g,itemId){const i=ITEM_BY_ID[itemId];if(!i)return {ok:false,message:'That item is unavailable.'};if(g.level<i.level)return {ok:false,message:`Level ${i.level} first, brave shopper!`};if(g.inventory.includes(i.id)){g.equipped[i.slot]=i.id;return {ok:true,message:'Equipped from your collection.'};}const price=priceFor(g,i);if(g.gold<price)return {ok:false,message:`You need ${price-g.gold} more gold. Try a regular fight!`};g.gold-=price;g.inventory.push(i.id);g.equipped[i.slot]=i.id;return {ok:true,message:'A fine choice! Equipped and ready.'};}
export function allocatePoint(g,key){if(!ATTRIBUTES[key]||g.skillPoints<1||g.attributes[key]>=65)return false;g.attributes[key]++;g.skillPoints--;return true;}
export function xpNeeded(g){return 95+(g.level-1)*30;}
export function awardBattle(g,{won,champion=null,enemyLevel=g.level}={}){g.battles++;g[won?'wins':'losses']++;const difficulty=g.difficulty??1;let gold=won?Math.round((65+enemyLevel*20)*(1+g.attributes.charisma*.018)):difficulty===0?20:difficulty===1?10:0;let xp=won?80+enemyLevel*30:35+enemyLevel*10;const first=won&&champion&&!g.champions.includes(champion.id);if(first){g.champions.push(champion.id);gold+=100*champion.tier;xp+=90*champion.tier;}if(!won&&difficulty===2){const lost=Math.min(g.gold,Math.round(g.gold*.08));g.gold-=lost;}g.gold+=gold;g.xp+=xp;let levels=0;while(g.xp>=xpNeeded(g)&&g.level<30){g.xp-=xpNeeded(g);g.level++;g.skillPoints+=5;levels++;}return {gold,xp,levels,champion:first,finished:g.champions.length===7};}
export function qualifies(g,c){return g.level>=c.level&&g.wins>=c.wins&&(c.index===0||g.champions.includes(CHAMPIONS[c.index-1].id));}
export function makeOpponent(g,champion=null,rng=Math.random){const level=champion?.level||Math.max(1,g.level+(rng()<.35?1:0)),tier=champion?.tier||clamp(Math.ceil(level/2),1,7),styles=['aggressive','agile','defensive','pusher','charisma','balanced'],style=champion?.style||styles[Math.floor(rng()*styles.length)];const base=3+(level-1)*.68;const a=Object.fromEntries(Object.keys(ATTRIBUTES).map(k=>[k,Math.round(base+2)]));a[style==='agile'?'agility':style==='defensive'?'defence':style==='charisma'?'charisma':'strength']+=3;const n=makeGladiator({name:champion?.name||['Clovis Sandboots','Nora Knucklehelm','Gus the Loud','Tilda Tinshield'][Math.floor(rng()*4)],attributes:a});n.attributes=a;n.level=level;n.style=style;n.appearance={skin:['#d79a66','#a96749','#e6bc94','#80523c'][level%4],hair:['#543228','#bd7733','#e0d1b0'][tier%3],hairStyle:['mohawk','long','bald','spikes'][tier%4],beard:['full','none','moustache'][tier%3],eyes:style==='charisma'?'silly':'angry',body:style==='defensive'?1.2:style==='agile'?.87:1.05};n.equipped={weapon:`w-${champion?.weapon||['sword','axe','club','spear','mace'][level%5]}-${tier}`};for(const [i,s]of SLOTS.entries())if(champion||i<Math.min(7,level))n.equipped[s]=`a-${s}-${Math.max(1,tier-(champion?0:1))}`;return n;}
export function balancedDuel(g,{level=5,tier=3,weapon='sword'}={}){const n=clone(g);n.level=clamp(level,1,15);n.attributes=Object.fromEntries(Object.keys(ATTRIBUTES).map(k=>[k,6+Math.floor(n.level/2)]));n.equipped={weapon:`w-${weapon}-${tier}`,...Object.fromEntries(SLOTS.map(s=>[s,`a-${s}-${tier}`]))};return n;}
export class ArenaBattle{
 constructor(fighters,{ai=true,difficulty=1,theme='sand',rng=Math.random}={}){this.rng=rng;this.ai=ai;this.difficulty=difficulty;this.theme=theme;this.turn=0;this.turns=0;this.phase='ready';this.animation=null;this.winner=null;this.reason='';this.log=[];this.fighters=fighters.map((g,i)=>{const stats=fighterStats(g);return {...clone(g),equipment:equipment(g),stats,hp:stats.maxHp,energy:stats.maxEnergy,armor:stats.armor,x:i?700:300,guard:false,shaken:0};});if(ai){const f=this.fighters[1],factor=[.85,1,1.13][difficulty];f.hp=Math.round(f.hp*factor);f.stats.maxHp=f.hp;f.stats.damage*=factor;}}
 distance(){return Math.abs(this.fighters[1].x-this.fighters[0].x);}
 chance(action,index=this.turn){const f=this.fighters[index],t=this.fighters[1-index],a=ACTIONS[action];if(action==='taunt')return clamp(48+(f.attributes.charisma-t.attributes.charisma)*4,18,90);return clamp(76+(f.attributes.attack-t.attributes.defence)*2+f.stats.accuracy+(a.accuracy||0)-f.shaken*4-(t.guard?15:0),15,97);}
 hitChance(action,index=this.turn){const t=this.fighters[1-index];if(action==='taunt')return this.chance(action,index);const dodge=t.stats.dodge*(t.energy<5?.3:1),block=action==='shove'?0:t.stats.block+(t.guard?30:0);return Math.round(this.chance(action,index)*(1-dodge/100)*(1-block/100));}
 available(action,index=this.turn){const f=this.fighters[index],a=ACTIONS[action];if(!a||this.phase!=='ready'||index!==this.turn||f.energy<a.cost)return false;const d=this.distance();if(['quick','normal','power'].includes(action))return d<=f.stats.reach+35;if(action==='shove')return d<105;if(action==='charge')return d<=f.stats.reach+f.stats.jump+60&&d>85;if(action==='taunt')return d<420;if(['forward','jumpForward'].includes(action))return d>65;return true;}
 start(action){if(!this.available(action))return false;const f=this.fighters[this.turn];this.phase='animating';this.animation={action,index:this.turn,elapsed:0,duration:ACTIONS[action].duration,impact:false,from:this.fighters.map(x=>x.x),to:null,outcome:null};f.energy-=ACTIONS[action].cost;f.guard=false;return true;}
 resolve(){const z=this.animation;if(!z||z.impact)return;z.impact=true;const f=this.fighters[z.index],t=this.fighters[1-z.index],a=ACTIONS[z.action],dir=t.x>f.x?1:-1,d=this.distance();let outcome={text:'',reaction:'',damage:0};const move=n=>{f.x=clamp(f.x+dir*n,65,935);if((dir===1&&f.x>t.x-65)||(dir===-1&&f.x<t.x+65))f.x=t.x-dir*65;};
 if(['forward','back','jumpForward','jumpBack'].includes(z.action)){move((z.action.startsWith('jump')?f.stats.jump:f.stats.walk)*(['back','jumpBack'].includes(z.action)?-1:1));outcome.text='Positioned';}
 else if(z.action==='rest'){const n=Math.min(f.stats.maxEnergy-f.energy,f.stats.recovery);f.energy+=n;outcome.text=`+${n} energy`;outcome.reaction='rest';}
 else if(z.action==='defend'){f.guard=true;f.energy=Math.min(f.stats.maxEnergy,f.energy+4);outcome.text='Guard up';outcome.reaction='defend';}
 else if(z.action==='taunt'){if(this.rng()*100<this.chance('taunt')){const drain=8+Math.round(f.attributes.charisma*1.8);t.energy=Math.max(0,t.energy-drain);t.shaken=2;outcome.text=`Rattled! −${drain} energy`;outcome.reaction='hurt';}else outcome.text='Crowd boos!';}
 else{if(z.action==='charge')move(Math.max(0,d-f.stats.reach*.72));const roll=this.rng()*100;if(roll>=this.chance(z.action)){outcome.text='MISS!';outcome.reaction='dodge';}
 else if(this.rng()*100<t.stats.dodge*(t.energy<5?.3:1)){outcome.text='DODGED!';outcome.reaction='dodge';}
 else if(z.action!=='shove'&&this.rng()*100<t.stats.block+(t.guard?30:0)){outcome.text='BLOCKED!';outcome.reaction='block';t.energy=Math.max(0,t.energy-4);t.armor=Math.max(0,t.armor-2);}
 else{const crit=z.action!=='shove'&&this.rng()<Math.min(.2,.03+f.attributes.attack*.004);let raw=z.action==='shove'?Math.round(f.attributes.strength*.35):Math.round(f.stats.damage*a.power*(.88+this.rng()*.24)*(crit?1.5:1));if(t.guard)raw=Math.round(raw*.6);const absorb=Math.min(t.armor,Math.round(raw*.55));t.armor-=absorb;const damage=Math.max(1,raw-absorb);t.hp=Math.max(0,t.hp-damage);outcome.damage=damage;outcome.text=`${crit?'CRITICAL! ':''}−${damage}${absorb?' · armor −'+absorb:''}`;outcome.reaction=z.action==='power'||z.action==='shove'||z.action==='charge'?'knockback':'hurt';const push=z.action==='shove'?28+f.attributes.strength*3-t.attributes.strength*.6:6+(z.action==='power'?19:z.action==='charge'?27:2)+(f.equipment.weapon?.push||0)*40;t.x+=dir*Math.max(6,push);if(t.x<62||t.x>938){t.hp=0;outcome.text='RING OUT!';outcome.reaction='defeat';this.reason='arena edge';}}}
 if(f.shaken)f.shaken--;z.to=this.fighters.map(x=>x.x);z.outcome=outcome;this.log.push({actor:f.name,action:z.action,...outcome});this.log=this.log.slice(-80);if(t.hp<=0){this.winner=z.index;this.reason=this.reason||'knockout';} }
 tick(ms){if(this.phase!=='animating')return null;const z=this.animation;z.elapsed+=Math.max(0,Math.min(ms,100));let event=null;if(!z.impact&&z.elapsed>=z.duration*.48){this.resolve();event=z.outcome;}if(z.elapsed>=z.duration){if(this.winner!==null)this.phase='finished';else{this.turn=1-this.turn;this.turns++;this.phase=this.ai?'ready':'handoff';this.fighters[this.turn].energy=Math.min(this.fighters[this.turn].stats.maxEnergy,this.fighters[this.turn].energy+2);if(this.turns>=400){const ratios=this.fighters.map(f=>f.hp/f.stats.maxHp);this.winner=ratios[0]===ratios[1]?-1:ratios[0]>ratios[1]?0:1;this.reason='400-turn health decision';this.phase='finished';}}}return event;}
 ready(){if(this.phase==='handoff'){this.phase='ready';return true;}return false;}
 chooseAI(index=this.turn){const f=this.fighters[index],t=this.fighters[1-index],s=f.style||'balanced',d=this.distance(),legal=Object.keys(ACTIONS).filter(a=>this.available(a,index));const has=a=>legal.includes(a),edge=t.x<155||t.x>845,ownEdge=f.x<160||f.x>840;
 if(f.energy<10||f.energy<20&&d>200)return 'rest';if(edge&&has('shove'))return 'shove';if(ownEdge&&has('jumpForward')&&d>100)return 'jumpForward';if(s==='charisma'&&t.energy>20&&has('taunt')&&this.rng()<.55)return 'taunt';if(d>f.stats.reach+35){if(has('charge')&&f.energy>35&&['aggressive','champion'].includes(s))return 'charge';return has('jumpForward')&&f.energy>32?'jumpForward':has('forward')?'forward':'rest';}
 if(s==='pusher'&&has('shove'))return 'shove';if(s==='defensive'&&has('defend')&&!f.guard&&t.energy>28&&this.rng()<.35)return 'defend';if(s==='agile'&&has('quick'))return 'quick';if(has('power')&&f.energy>30&&(t.armor>10||t.hp<f.stats.damage*1.5)&&this.chance('power')>45)return 'power';if(has('normal'))return 'normal';return has('quick')?'quick':'rest';}
}
